mapper.select:
select * from ( select row_number() over (order by place_list.p_no desc) as rn, place_list.* from ( select p.*, coalesce(r.reserved_count, 0) as reservedCount from place p left join ( select r_p_no, count(*) as reserved_count from reservation group by r_p_no ) r on p.p_no = r.r_p_no
( p.p_pname like '%'||#{keyword}||'%' or p.p_place like '%'||#{keyword}||'%' or p.p_explain like '%'||#{keyword}||'%' )
and p.p_place like '%'||#{region}||'%'
and p.p_book = #{book}
) place_list ) where rn <= #{pageNum}
